mapper.select:
select ac.id, ac.name, activity_time_start, activity_time_end, ac.effect_time, ac.status, case when ac.activity_time_start > #{now} then 2 when ac.activity_time_start <= #{now} and ac.activity_time_end >= #{now} then 3 when ac.activity_time_end < #{now} then 1 end sort from cus_activity ac left join cus_business_park_relation r on ac.id = r.business_id
ac.deleted = 0 and ac.effect_time <= #{now} and r.business_type = 3 and r.deleted = 0 and r.park_org_id =#{parkOrgId}
group by ac.id order by sort desc limit 5
